create table public.posts (id bigint generated by default as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,username text not null,content text not null check(char_length(content)<=500),created_at timestamptz not null default now());
create table public.replies (id bigint generated by default as identity primary key,post_id bigint not null references public.posts(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,username text not null,type text not null check(type in ('text','drawing')),content text not null,created_at timestamptz not null default now());
alter table public.posts enable row level security; alter table public.replies enable row level security;
create policy "read posts" on public.posts for select to authenticated using(true);
create policy "create posts" on public.posts for insert to authenticated with check(auth.uid()=user_id);
create policy "delete own posts" on public.posts for delete to authenticated using(auth.uid()=user_id);
create policy "read replies" on public.replies for select to authenticated using(true);
create policy "create replies" on public.replies for insert to authenticated with check(auth.uid()=user_id);
create policy "delete own replies" on public.replies for delete to authenticated using(auth.uid()=user_id);